def unique_jobs(rows):
    # Stable deduplication by (source, source_id) where source_id is not None/empty.
    # If source_id is None or empty string (after strip), keep row separately.
    seen = {}
    result = []
    for row in rows:
        source = row['source']
        source_id = row['source_id']
        if source_id is None or (isinstance(source_id, str) and source_id.strip() == ""):
            # missing source_id -> keep row
            result.append(row)
        else:
            key = (source, source_id)
            if key in seen:
                # duplicate, skip
                continue
            else:
                seen[key] = True
                result.append(row)
    return result
